def compute(vars):
    decrease = vars["v1"]
    net_revenue = vars["v2"]
    if net_revenue == 0:
        return None
    ratio = decrease / net_revenue
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "decrease": decrease,
            "net_revenue": net_revenue,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
